import{XO_CONFIG as N}from"./config.min.js";export function interceptTarget({start:x,at:t,heading:r=null,throttle:m,extra:u=0,maxTicks:n=N.lead.maxTicks}={}){const e=r&&Number(r.x)||0,y=r&&Number(r.y)||0,c=Math.max(.01,Number(m)||0);let o=1/0;c-e>1e-6&&(o=((t.x*c-e*x.x)/(c-e)-x.x)/c),o>=0||(o=0);const i=Number.isFinite(n)&&n>=0?n:1/0;o=Math.min(o,i);const s=o+Math.max(0,Number(u)||0);return{x:t.x+e*s,y:t.y+y*s,ticks:o}}export function strideError({at:x,heading:t,land:r,flightTicks:m}){const u=t&&Number(t.x)||0,n=t&&Number(t.y)||0,e=Math.max(0,Number(m)||0);return Math.hypot(r.x-(x.x+u*e),r.y-(x.y+n*e))}
